	ay_init(&AYInfo.chip0);
	ay_init(&AYInfo.chip1);
	AYInfo.module = (unsigned char *)music_data;
	AYInfo.module_len = music_data_size;
	PT3_Init(&AYInfo);

	int frame = 0;
	int loop = 0;

	AYSongInfo *info = &AYInfo;
	PT3_SongInfo *data = &info->data;
	PT3_File *header = (PT3_File *) info->module;

	printf("const unsigned char frame_data[][14] = {\n");

	clock_t t = clock();
	for (;;) {
		int pos = PT3.CurrentPosition;

		info->chip0.reg[13] = 255;	// added by joric
		info->chip1.reg[13] = 255;	// added by joric

